1: /** @module @category Feature Flags */
2: import { getGlobalStore } from '@openmrs/esm-state';
3: 
4: export interface FeatureFlagsStore {
5:   flags: { [flagName: string]: FeatureFlag };
6: }
7: 
8: export interface FeatureFlag {
9:   enabled: boolean;
10:   label: string;
11:   description: string;
12: }
13: 
14: const initialFeatureFlags = { flags: getFeatureFlagsFromLocalStorage() };
15: 
16: /** @internal */
17: export const featureFlagsStore = getGlobalStore<FeatureFlagsStore>('feature-flags', initialFeatureFlags);
18: 
19: featureFlagsStore.subscribe((state) => {
20:   for (const [flagName, flag] of Object.entries(state.flags)) {
21:     localStorage.setItem(`openmrs:feature-flag:${flagName}`, flag.enabled.toString());
22:     localStorage.setItem(
23:       `openmrs:feature-flag-meta:${flagName}`,
24:       JSON.stringify({ label: flag.label, description: flag.description }),
25:     );
26:   }
27: });
28: 
29: function getFeatureFlagsFromLocalStorage() {
30:   const flags: FeatureFlagsStore['flags'] = {};
31:   for (const key of Object.keys(localStorage)) {
32:     if (key.startsWith('openmrs:feature-flag:')) {
33:       const flagName = key.replace('openmrs:feature-flag:', '');
34:       const meta = JSON.parse(localStorage.getItem(`openmrs:feature-flag-meta:${flagName}`) || '{}');
35:       flags[flagName] = {
36:         enabled: localStorage.getItem(key) === 'true',
37:         ...meta,
38:       };
39:     }
40:   }
41:   return flags;
42: }
