44: /**
45:  * This function creates a feature flag. Call it in top-level code anywhere. It will
46:  * not reset whether the flag is enabled or not, so it's safe to call it multiple times.
47:  * Once a feature flag is created, it will appear with a toggle in the Implementer Tools.
48:  * It can then be used to turn on or off features in the code.
49:  *
50:  * @param flagName A code-friendly name for the flag, which will be used to reference it in code
51:  * @param label A human-friendly name which will be displayed in the Implementer Tools
52:  * @param description An explanation of what the flag does, which will be displayed in the Implementer Tools
53:  */
54: export function registerFeatureFlag(flagName: string, label: string, description: string) {
55:   featureFlagsStore.setState((state) => ({
56:     flags: {
57:       ...state.flags,
58:       [flagName]: {
59:         enabled: state.flags[flagName]?.enabled ?? false,
60:         label,
61:         description,
62:       },
63:     },
64:   }));
65: }
66: 
67: /**
68:  * This function removes feature flags from local storage that no longer exist in the current state.
69:  */
70: export function cleanupObsoleteFeatureFlags() {
71:   const flags = featureFlagsStore.getState().flags;
72:   Object.keys(localStorage)
73:     .filter((key) => key.startsWith('openmrs:feature-flag:'))
74:     .forEach((key) => {
75:       const flagName = key.replace('openmrs:feature-flag:', '');
76:       if (!flags[flagName]) {
77:         localStorage.removeItem(key);
78:         localStorage.removeItem(`openmrs:feature-flag-meta:${flagName}`);
79:       }
80:     });
81: }
82: 
83: /**
84:  * Use this function to access the current value of the feature flag.
85:  *
86:  * If you are using React, use `useFeatureFlag` instead.
87:  *
